/** Every tunable for this field lives here (AI_AGENT_RULES § R-57). */

export interface Option {
  label: string;
  value: string;
}

export interface InfiniteSourcePreset {
  name: string;
  baseUrl: string;
  labelKey: string;
  valueKey: string;
  dataPath: string;
}

/** Rows requested per page. */
export const PAGE_SIZE = 10;

/** How long typing settles before a new search request is issued. */
export const SEARCH_DEBOUNCE_MS = 300;

export const INFINITE_SOURCES: InfiniteSourcePreset[] = [
  { name: "Products", baseUrl: "https://dummyjson.com/products/search", labelKey: "title", valueKey: "id", dataPath: "products" },
  { name: "Users", baseUrl: "https://dummyjson.com/users/search", labelKey: "firstName", valueKey: "id", dataPath: "users" },
  { name: "Recipes", baseUrl: "https://dummyjson.com/recipes/search", labelKey: "name", valueKey: "id", dataPath: "recipes" },
];

export function getInfiniteSourceByName(name: string | undefined): InfiniteSourcePreset {
  if (!name) return INFINITE_SOURCES[0];
  return INFINITE_SOURCES.find((s) => s.name === name) ?? INFINITE_SOURCES[0];
}

/**
 * The only file in this bundle that talks to the network (§ R-55).
 * Swap the base URL, headers or client here — nothing else needs to change.
 */
import { PAGE_SIZE, type Option } from "./constants";

export interface OptionsPage {
  options: Option[];
  hasMore: boolean;
}

async function request(url: string, signal?: AbortSignal): Promise<unknown> {
  const response = await fetch(url, { signal });
  if (!response.ok) throw new Error("Request failed with status " + response.status);
  return response.json();
}

export async function fetchOptionsPage(
  baseUrl: string,
  labelKey: string,
  valueKey: string,
  search: string,
  offset: number,
  signal?: AbortSignal
): Promise<OptionsPage> {
  const url = new URL(baseUrl);
  url.searchParams.set("limit", String(PAGE_SIZE));
  url.searchParams.set("skip", String(offset));
  if (search) url.searchParams.set("q", search);

  const payload = await request(url.toString(), signal);
  const raw = payload as Record<string, unknown>;
  const items = Array.isArray(payload)
    ? (payload as unknown[])
    : ([raw.products, raw.users, raw.posts, raw.recipes].find((v) => Array.isArray(v)) as unknown[] | undefined) ?? [];
  const total = typeof raw.total === "number" ? raw.total : items.length;

  return {
    options: items.map((item: unknown) => {
      const rec = item as Record<string, unknown>;
      return {
        label: String(rec[labelKey] ?? rec.title ?? rec.name ?? ""),
        value: String(rec[valueKey] ?? rec.id ?? ""),
      };
    }),
    hasMore: offset + PAGE_SIZE < total,
  };
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

import { PAGE_SIZE, type Option } from "./constants";
import { fetchOptionsPage } from "./services";

/**
 * The ONLY caller of services.ts (§ R-55). Its name, arguments and return
 * shape match the react-query implementation exactly, so the component file
 * is byte-identical whichever transport was selected.
 */
export function useInfiniteOptions(baseUrl: string, labelKey: string, valueKey: string, search: string) {
  const [options, setOptions] = useState<Option[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isFetchingNextPage, setIsFetchingNextPage] = useState(false);
  const [hasNextPage, setHasNextPage] = useState(false);

  const offsetRef = useRef(0);
  const loadingRef = useRef(false);
  const controllerRef = useRef<AbortController | null>(null);

  // Any change of source or search term restarts pagination from page one.
  useEffect(() => {
    const controller = new AbortController();
    controllerRef.current = controller;
    offsetRef.current = 0;
    loadingRef.current = true;
    let active = true;

    setOptions([]);
    setIsLoading(true);

    fetchOptionsPage(baseUrl, labelKey, valueKey, search, 0, controller.signal)
      .then((page) => {
        if (!active) return;
        setOptions(page.options);
        setHasNextPage(page.hasMore);
      })
      .catch(() => {
        if (active) setHasNextPage(false);
      })
      .finally(() => {
        if (!active) return;
        loadingRef.current = false;
        setIsLoading(false);
      });

    return () => {
      active = false;
      loadingRef.current = false;
      controller.abort();
    };
  }, [baseUrl, labelKey, valueKey, search]);

  const fetchNextPage = useCallback(() => {
    if (loadingRef.current || !hasNextPage) return;

    const nextOffset = offsetRef.current + PAGE_SIZE;
    loadingRef.current = true;
    setIsFetchingNextPage(true);

    fetchOptionsPage(baseUrl, labelKey, valueKey, search, nextOffset, controllerRef.current?.signal)
      .then((page) => {
        offsetRef.current = nextOffset;
        setOptions((prev) => [...prev, ...page.options]);
        setHasNextPage(page.hasMore);
      })
      .catch(() => {
        setHasNextPage(false);
      })
      .finally(() => {
        loadingRef.current = false;
        setIsFetchingNextPage(false);
      });
  }, [baseUrl, labelKey, valueKey, search, hasNextPage]);

  return { options, isLoading, fetchNextPage, hasNextPage, isFetchingNextPage };
}

"use client";

import { useState, useRef, useEffect, useCallback } from "react";
import { Check, ChevronsUpDown, Loader2 } from "lucide-react";

import { cn } from "@/lib/utils";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { ScrollArea } from "@/components/ui/scroll-area";

import { INFINITE_SOURCES, SEARCH_DEBOUNCE_MS, getInfiniteSourceByName } from "./constants";
import { useInfiniteOptions } from "./hooks";

function ScrollSentinel({ onVisible, loading }: { onVisible: () => void; loading: boolean }) {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !loading) onVisible();
      },
      { threshold: 0.1 }
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [onVisible, loading]);

  return (
    <div ref={ref} className="flex items-center justify-center py-2">
      {loading && <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />}
    </div>
  );
}

export function InfiniteFieldAutoSelect() {
  const [source, setSource] = useState(getInfiniteSourceByName("Products"));
  const [search, setSearch] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");
  const [value, setValue] = useState("");
  const timerRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  const handleSearch = (v: string) => {
    setSearch(v);
    if (timerRef.current) clearTimeout(timerRef.current);
    timerRef.current = setTimeout(() => setDebouncedSearch(v), SEARCH_DEBOUNCE_MS);
  };

  const {
    options: allOptions,
    isLoading,
    fetchNextPage,
    hasNextPage,
    isFetchingNextPage,
  } = useInfiniteOptions(source.baseUrl, source.labelKey, source.valueKey, debouncedSearch);

  const loadMore = useCallback(() => {
    if (hasNextPage) fetchNextPage();
  }, [hasNextPage, fetchNextPage]);

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap gap-2">
        {INFINITE_SOURCES.map((s) => (
          <Button key={s.name} size="sm" variant={source.name === s.name ? "default" : "outline"} onClick={() => setSource(s)}>
            {s.name}
          </Button>
        ))}
      </div>
      <div className="space-y-2">
        <Label className="text-sm font-medium">Infinite select — {source.name}</Label>
        <Popover>
          <PopoverTrigger asChild>
            <Button variant="outline" className="w-full justify-between">
              {value ? allOptions.find((o) => o.value === value)?.label || value : "Select..."}
              <ChevronsUpDown className="ms-2 h-4 w-4 shrink-0 opacity-50" />
            </Button>
          </PopoverTrigger>
          <PopoverContent className="w-[--radix-popover-trigger-width] p-0">
            <div className="p-2 border-b">
              <Input
                placeholder={"Search..."}
                value={search}
                onChange={(e) => handleSearch(e.target.value)}
                className="h-8 text-sm"
                autoFocus
                onPointerDown={(e) => e.stopPropagation()}
              />
            </div>
            <ScrollArea className="h-[200px]">
              {isLoading ? (
                <div className="flex items-center justify-center py-8">
                  <Loader2 className="h-4 w-4 animate-spin" />
                </div>
              ) : allOptions.length === 0 ? (
                <p className="text-sm text-muted-foreground text-center py-4">No results</p>
              ) : (
                <div className="p-1">
                  {allOptions.map((o) => (
                    <button
                      key={o.value}
                      type="button"
                      className={cn(
                        "w-full text-start px-2 py-1.5 text-sm rounded-sm hover:bg-accent flex items-center gap-2",
                        value === o.value && "bg-accent"
                      )}
                      onClick={() => setValue(o.value)}
                    >
                      <Check className={cn("h-4 w-4 shrink-0", value === o.value ? "opacity-100" : "opacity-0")} />
                      {o.label}
                    </button>
                  ))}
                  {hasNextPage && <ScrollSentinel onVisible={loadMore} loading={isFetchingNextPage} />}
                </div>
              )}
            </ScrollArea>
          </PopoverContent>
        </Popover>
      </div>
    </div>
  );
}

